DROP TABLE IF EXISTS auditoria CASCADE;
DROP TABLE IF EXISTS pilotos CASCADE;
CREATE TABLE pilotos (
    id GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    creditos NUMERIC(10,2) DEFAULT 0.00
);
CREATE TABLE auditoria (
    id GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    piloto_id INT,
    viejo_saldo NUMERIC(10,2),
    nuevo_saldo NUMERIC(10,2),
    fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE OR REPLACE FUNCTION auditar_saldo()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO auditoria(piloto_id, viejo_saldo, nuevo_saldo)
    VALUES (NEW.id, OLD.creditos, NEW.creditos);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
INSERT INTO pilotos (nombre, creditos) VALUES ('Luke Skywalker', 1000.00);

