-- que acepte un ID de piloto (INTEGER) y un monto (NUMERIC) y ejecute:
-- UPDATE pilotos SET creditos = creditos + monto WHERE id = p_id;
-- Retorna VOID.

CREATE OR REPLACE FUNCTION adicionar_creditos(p_id INTEGER, p_monto NUMERIC)
RETURNS VOID AS $$
BEGIN
    UPDATE pilotos SET creditos = creditos + p_monto WHERE id = p_id;
END;
$$ LANGUAGE plpgsql;

